#include <stdlib.h>
#include <string.h>
int main(void){int n,i;static long long a[500005];if(scanf("%d",&n)!=1)return 1;for(i=0;i<n;i++)scanf("%lld",&a[i]);long long s=0;for(i=0;i+1<n;i++){long long d=a[i+1]-a[i];if(d<0)d=-d;s+=d;}printf("%lld\n",s);return 0;}
